class Solution { public:int numberOfPaths(vector<vector<int>>& grid,int k){const int mod=1000000007;int rows=grid.size(),columns=grid[0].size();vector dp(rows,vector(columns,vector<int>(k)));dp[0][0][grid[0][0]%k]=1;for(int r=0;r<rows;++r)for(int c=0;c<columns;++c)for(int remainder=0;remainder<k;++remainder){int ways=dp[r][c][remainder];if(r+1<rows){int next=(remainder+grid[r+1][c])%k;dp[r+1][c][next]=(dp[r+1][c][next]+ways)%mod;}if(c+1<columns){int next=(remainder+grid[r][c+1])%k;dp[r][c+1][next]=(dp[r][c+1][next]+ways)%mod;}}return dp.back().back()[0];} };
